/**
 * Humanoid library catalog (metadata only).
 *
 * `public/catalog/humanoid-summary.json` is generated by
 * `tools/catalog/build-summary.mjs` from the upstream catalog branch. It contains
 * records only: no model bytes, no private storage locators, no hashes. Every
 * entry must be re-linked to a local file before DEX//SCULPT can edit it.
 */
export interface CatalogAsset {
  id: string;
  name: string;
  type: string;
  family: string | null;
  joints: number | null;
  clips: number | null;
  triangles: number | null;
  bytes: number | null;
  license: string | null;
  qa: string | null;
  tags: string[];
}

export interface CatalogSource {
  id: string;
  name: string;
  kind?: string;
  license?: string | null;
  licenseUrl?: string | null;
  officialUrl?: string | null;
  access?: string;
  notes?: string;
  assetCount: number;
  assetTypes: Record<string, number>;
  skeletonFamilies: Record<string, number>;
  status?: string | null;
}

export interface CatalogFamily {
  id: string;
  jointCountRange: [number, number] | null;
  authoringConvention: string | null;
  rootBone: string | null;
  pelvisBone: string | null;
  memberSources: string[] | null;
  embeddedAnimationClips: number | null;
  directClipSharing: string | null;
}

export interface CatalogSummary {
  schema: string;
  generatedFrom: { repository: string; branch: string; commit: string; catalogGeneratedUtc: string | null; catalogSchema: string | null };
  notes: string[];
  totals: { assets: number; sources: number; rocketboxAssets: number; animatedAssets: number; families: number };
  sources: CatalogSource[];
  families: CatalogFamily[];
  retargetingWorkflows: { id: string; sourceFamily: string; targetFamily: string; status: string; method: string | null }[];
  incompatiblePairs: { pair: string[]; reason: string | null }[];
  assets: CatalogAsset[];
}

export type CatalogFilter = 'all' | 'characters' | 'animated' | 'static' | 'accessories' | 'animations';

let cache: CatalogSummary | null = null;
let loadError: string | null = null;

export async function loadCatalog(url = './catalog/humanoid-summary.json'): Promise<CatalogSummary | null> {
  if (cache) return cache;
  try {
    const response = await fetch(url, { cache: 'no-cache' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const json = (await response.json()) as CatalogSummary;
    if (json.schema !== 'dexsculpt/humanoid-catalog-summary@1') throw new Error(`Unexpected catalog schema ${json.schema}`);
    cache = json;
    loadError = null;
    return cache;
  } catch (error) {
    loadError = (error as Error).message;
    return null;
  }
}

export function catalogError(): string | null {
  return loadError;
}

export function filterAssets(summary: CatalogSummary, query: string, filter: CatalogFilter): CatalogAsset[] {
  const q = query.trim().toLowerCase();
  return summary.assets.filter((asset) => {
    if (filter === 'characters' && asset.type !== 'character') return false;
    if (filter === 'animated' && !(asset.clips && asset.clips > 0)) return false;
    if (filter === 'static' && (asset.clips ?? 0) > 0) return false;
    if (filter === 'accessories' && !/accessor|prop|outfit|hair/i.test(asset.type)) return false;
    if (filter === 'animations' && asset.type !== 'animation_pack') return false;
    if (!q) return true;
    return (
      asset.name.toLowerCase().includes(q) ||
      asset.id.toLowerCase().includes(q) ||
      (asset.family ?? '').toLowerCase().includes(q) ||
      asset.type.toLowerCase().includes(q) ||
      asset.tags.some((tag) => tag.toLowerCase().includes(q))
    );
  });
}

export function familyOf(summary: CatalogSummary | null, id: string | null): CatalogFamily | undefined {
  if (!summary || !id) return undefined;
  return summary.families.find((f) => f.id === id);
}

export function sourceOf(summary: CatalogSummary | null, id: string | null): CatalogSource | undefined {
  if (!summary || !id) return undefined;
  return summary.sources.find((s) => s.id === id);
}

export function assetSourceId(asset: CatalogAsset): string | null {
  const slash = asset.id.indexOf('/');
  return slash > 0 ? asset.id.slice(0, slash) : null;
}

export function compatibilityNote(summary: CatalogSummary | null, family: string | null): string {
  if (!summary) return 'Catalog metadata unavailable.';
  if (!family) return 'No skeleton family recorded — treat as unknown compatibility.';
  const info = familyOf(summary, family);
  if (!info) return `Skeleton family "${family}" is not described in the compatibility matrix.`;
  const range = info.jointCountRange ? `${info.jointCountRange[0]}–${info.jointCountRange[1]} joints` : 'joint count not recorded';
  return `${family} · ${range}${info.rootBone ? ` · root ${info.rootBone}` : ''}${info.directClipSharing ? `. ${info.directClipSharing}` : ''}`;
}
